 'coastal-coupe':{url:'/cruise/vehicle/rx7-fc-optimized.glb',rotation:Math.PI,length:4.3,eye:[-.36,1.12,.25],wheelbase:2.43,track:1.45},
 'classic-coupe':{url:'/cruise/vehicle/gto-candidate/gto-low.glb',rotation:0,length:4.8,eye:[-.3024,1.29,.042],wheelbase:2.85,track:1.55},
