  if(!controls.active){controls.keys.clear();controls.brakeHeld=false;if(controls.stick)Object.assign(controls.stick,{x:0,y:0})}
  if(settings.paused||settings.hidden){handling.reset();if(custom)hero.drive.apply(hero.v)}
