  const eye=new T.Object3D();eye.position.fromArray(d.eye);root.add(eye)
  const lights=sharedLights.heads
  bindCruiseLighting(root);scene.add(root);cars.probe?.hide.push(root)
  const b=new T.Box3().setFromObject(normalized).getSize(new T.Vector3()),length=d.length,width=Math.min(2.2,Math.max(1.6,b.x))
  hero.v.spec={...hero.v.spec,length,width,wheelbase:d.wheelbase,track:d.track,wheelR:wheels[0]?.radius||.34,
   wheels:[[-d.track/2,-d.wheelbase/2],[d.track/2,-d.wheelbase/2],[-d.track/2,d.wheelbase/2],[d.track/2,d.wheelbase/2]],
   circles:[-.35,0,.35].map(t=>[t*length,width*.49]),idle:id==='countach'?850:750,redline:id==='countach'?7500:6000}
  const previous=custom
  custom={root,wheels,body,eye,owned,lights,disposeWheels,bounds:new T.Box3().setFromObject(root)}
  if(previous){scene.remove(previous.root);for(const m of previous.owned)m.dispose();previous.disposeWheels?.();const i=cars.probe?.hide.indexOf(previous.root);if(i>=0)cars.probe.hide.splice(i,1)}
  originalRoot.visible=false
