// Buena Onda house placements in the City drive. Static artwork keeps the
// product boards cheap to render and never starts an extra video or audio path.
const products=[
  {id:'catalog-miami-soundscapes',asset:'miami-soundscapes',z:-245,destination:'/items/miami-soundscapes-cassette-tape-buena-onda-edition-a62d932f'},
  {id:'catalog-low-cabinet',asset:'low-cabinet',z:-135,destination:'/items/low-cabinet-no-4'},
  {id:'gta-vi-official',asset:'gta-vi-official-cover',z:0,destination:'https://www.rockstargames.com/VI/editions'},
  {id:'catalog-instant-camera',asset:'instant-camera',z:135,destination:'/items/polaroid-onestep-600-instant-camera-with-original-box-1781036708155'},
  {id:'catalog-racing-jacket',asset:'racing-jacket',z:245,destination:'/items/1990s-nascar-winston-cup-dupont-automotive-finishes-jacket-d00f31ea'},
]

export function buildProductBillboards(THREE,scene){
 const group=new THREE.Group()
 group.name='Buena Onda product billboards'
 const loader=new THREE.TextureLoader()
 const frameMaterial=new THREE.MeshStandardMaterial({color:0x17242a,metalness:.3,roughness:.75})
 const postMaterial=new THREE.MeshStandardMaterial({color:0x344143,metalness:.35,roughness:.7})
 for(const product of products){
  const board=new THREE.Group()
  board.name=`Buena Onda ${product.asset}`
  board.userData.cruiseCampaignId=product.id
  board.userData.destination=product.destination
  board.position.set(-8.3,5.5,product.z)
  // Face an approaching driver on each half of Ocean Drive, not side-on.
  board.rotation.y=product.z<0?-.65:-2.5
  const backing=new THREE.Mesh(new THREE.BoxGeometry(10.25,4.42,.2),frameMaterial)
  backing.position.z=-.12
  backing.castShadow=false
  backing.receiveShadow=false
  board.add(backing)
  const face=new THREE.Mesh(new THREE.PlaneGeometry(10,4.17),new THREE.MeshBasicMaterial({color:0xffffff,side:THREE.DoubleSide,toneMapped:false}))
  face.position.z=.01
  face.userData.cruiseCampaignId=product.id
  face.userData.destination=product.destination
  if(product.id==='gta-vi-official'){
   const canvas=document.createElement('canvas');canvas.width=1024;canvas.height=428
   const context=canvas.getContext('2d'),texture=new THREE.CanvasTexture(canvas)
   texture.colorSpace=THREE.SRGBColorSpace;texture.anisotropy=8
   const paint=image=>{
    context.fillStyle='#1b0b2d';context.fillRect(0,0,1024,428)
    if(image){const width=image.naturalWidth*428/image.naturalHeight;context.drawImage(image,24,0,width,428)}
    context.fillStyle='#ee91ba';context.font='700 25px Arial,sans-serif';context.fillText('ROCKSTAR GAMES',390,70)
    context.fillStyle='#fff4ed';context.font='800 76px Arial,sans-serif';context.fillText('GRAND THEFT',390,190,600);context.fillText('AUTO VI',390,270,600)
    context.font='600 34px Arial,sans-serif';context.fillText('EXPLORE THE EDITIONS  >',390,368)
    texture.needsUpdate=true
   }
   paint(null)
   const image=new Image();image.onload=()=>{paint(image);face.userData.posterLoaded=true};image.src='/cruise/ads/gta-vi-official-cover.jpg'
   face.material.map=texture
  }else face.material.map=loader.load(`/cruise/campaigns/product-ads/${product.asset}.png`,texture=>{texture.colorSpace=THREE.SRGBColorSpace;texture.anisotropy=8;face.material.needsUpdate=true})
  board.add(face)
  for(const x of[-3.1,3.1]){
   const post=new THREE.Mesh(new THREE.BoxGeometry(.24,3.45,.24),postMaterial)
   post.position.set(x,-3.92,-.18)
   post.castShadow=false
   board.add(post)
  }
  group.add(board)
 }
 scene.add(group)
 return group
}
