import * as T from 'three'
import {CruiseDirector} from './cruise-director.js'
import {cinemaRig,wheelShake} from './cruise-look.js'
import {armBlocked} from './vehicles/camera.js'

/** Adapt Cruise's existing director to the source game's moving world coordinates. */
export function createCruiseCinematic(vehicles,camera,boxes){
 let vehicle=null,distance=0,active=false,time=0,nextInsert=14,insert=null,until=0,index=0
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches
 const route={length:1000000,sample(m){
  const ahead=m-distance,v=vehicle
  return {x:v.x-Math.sin(v.yaw)*ahead,z:v.z-Math.cos(v.yaw)*ahead,yaw:v.yaw,streetName:'Ocean Drive'}
 }}
 const buildings=boxes.filter(b=>b.min&&b.max.y>1).map((b,i)=>({id:String(i),height:b.max.y,points:[[b.min.x,b.min.z],[b.max.x,b.min.z],[b.max.x,b.max.z],[b.min.x,b.max.z]]}))
 const director=new CruiseDirector(route,{buildings},[],[],7)
 const position=new T.Vector3(),target=new T.Vector3(),origin=new T.Vector3()
 let shot=null
 const api={
  snapshot:()=>({...director.snapshot(),shot:insert||shot,insert}),
  force:shot=>{insert=null;nextInsert=time+14;director.force(shot)},
  reset(){active=false;insert=null;shot=null},
  update(dt,v,rig){
   if(!active){director.reset();time=0;nextInsert=14;index=0;active=true}
   vehicle=v;time+=Math.min(dt,.1);distance+=Math.abs(v.lon)*Math.min(dt,.1)
   const traffic=vehicles.world.dynamic().filter(c=>c.r>.6&&Math.abs((c.x-v.x)*Math.cos(v.yaw)-(c.z-v.z)*Math.sin(v.yaw))<3).map(c=>({distance:distance-(c.x-v.x)*Math.sin(v.yaw)-(c.z-v.z)*Math.cos(v.yaw)}))
   const bounds=rig.bounds
   const frame=director.update({dt,distance,speed:Math.abs(v.lon),lateral:0,aspect:camera.aspect,reduced,carMin:bounds.min,carMax:bounds.max,traffic,kick:0,phrase:0,beatLive:false,night:rig.night?1:0})
   origin.set(v.x,v.baseT+v.airY,v.z)
   position.copy(frame.position).add(origin)
   target.copy(frame.target).add(origin)
   let fov=frame.fov;shot=frame.shot
   if(insert&&time>=until){insert=null;nextInsert=time+30}
   if(!insert&&time>=nextInsert){insert=['wheel','wheelClose'][index++%2];until=time+5.5}
   if(insert){
    const pose=cinemaRig(insert,bounds),shake=wheelShake(time,Math.abs(v.lon),reduced)
    position.fromArray(pose.position);target.fromArray(pose.target);position.y+=shake;target.y+=shake*.4
    position.applyQuaternion(rig.root.quaternion).add(rig.root.position)
    target.applyQuaternion(rig.root.quaternion).add(rig.root.position)
    fov=camera.aspect<1?pose.fovPortrait:pose.fov
    if(armBlocked(vehicles.world.grid,position.x,position.y,position.z,.15)){
     insert=null;nextInsert=time+10;position.copy(frame.position).add(origin);target.copy(frame.target).add(origin);fov=frame.fov
    }
   }
   camera.position.copy(position);camera.lookAt(target)
   if(camera.fov!==fov){camera.fov=fov;camera.updateProjectionMatrix()}
  },
 }
 return api
}
