import {createVehicleFeel,stepVehicleFeel} from './cruise-vehicle-feel.js'

// Native tires/collisions still determine the route. The same sprung-body model
// used by Highway and Retrowave presents the acceleration of this free-driving car.
export function createCruiseHandling(){
 const response=createVehicleFeel()
 let distance=0,previousSpeed=null
 return {response,
  reset(){Object.assign(response,createVehicleFeel());previousSpeed=null},
  update(v,dt,paused=false,reduced=false){
   if(!Number.isFinite(dt)||dt<=0)return response
   const speed=Math.abs(v.lon),acceleration=previousSpeed===null?0:(v.lon-previousSpeed)/dt
   previousSpeed=v.lon;distance+=speed*Math.min(dt,.1)
   const curvature=speed>.4?-v.turn/v.lon:0
   return stepVehicleFeel(response,{distance,speed,acceleration,curvature,wheel:0,paused,reduced,focused:false},dt)
  },
 }
}
