// Daylight is the upstream reference. One shared uniform also colors the sky,
// aerial perspective and water reflections when Cruise changes to night.
export const cruiseNight={value:0}
export function bindCruiseLighting(scene){
 const seen=new Set()
 scene.traverse(o=>{for(const m of [].concat(o.material||[])){
  if(seen.has(m))continue;seen.add(m)
  if(m.uniforms)m.uniforms.uCruiseNight=cruiseNight
  const compile=m.onBeforeCompile,cache=m.customProgramCacheKey.bind(m)
  const key=cache()
  m.onBeforeCompile=function(shader,renderer){compile.call(this,shader,renderer);shader.uniforms.uCruiseNight=cruiseNight}
  m.customProgramCacheKey=()=>key+'-cruise-light-v1'
 }})
}
